#!/usr/bin/env node
/**
 * Emulator smoke test.
 *
 * Runs the real compiled mGBA core in a real browser against the original
 * fixture ROM (`fixtures/test-rom.gba`, generated by `npm run rom:fixture`) and
 * asserts that it boots, renders, animates, reacts to input, and exposes save
 * state / battery save / rewind APIs.
 *
 * This is intentionally separate from the unit test suite (vitest/happy-dom has
 * no WebAssembly threads). It is also separate from CI by default: it needs a
 * Chromium binary. Point `BROWSERGBA_CHROMIUM` at one to run it, otherwise the
 * script explains what is missing and exits without failing the build.
 *
 *   BROWSERGBA_CHROMIUM=/path/to/chrome npm run test:browser
 */
import { spawn } from 'node:child_process';
import { access, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { launchBrowser, skipMessage } from './harness.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const PORT = Number(process.env.BROWSERGBA_SMOKE_PORT ?? 4319);
const BASE = `http://127.0.0.1:${PORT}`;

/** Minimal static file server that sends the cross-origin isolation headers. */
async function startServer() {
  const { createServer } = await import('node:http');
  const { readFile } = await import('node:fs/promises');

  const types = {
    '.html': 'text/html; charset=utf-8',
    '.js': 'text/javascript; charset=utf-8',
    '.mjs': 'text/javascript; charset=utf-8',
    '.json': 'application/json; charset=utf-8',
    '.wasm': 'application/wasm',
    '.png': 'image/png',
    '.svg': 'image/svg+xml',
    '.css': 'text/css; charset=utf-8',
    '.map': 'application/json; charset=utf-8',
  };

  const server = createServer(async (req, res) => {
    const url = new URL(req.url ?? '/', BASE);
    const relative = decodeURIComponent(url.pathname).replace(/^\/+/, '');

    // Mirrors how Vite serves the app: `public/` is the web root, with the
    // repo root exposing test fixtures and probe pages alongside it.
    const searchRoots = [path.join(root, 'public'), path.join(root, 'fixtures'), root];
    let filePath = null;
    for (const base of searchRoots) {
      const candidate = path.join(base, relative || 'index.html');
      try {
        const { stat } = await import('node:fs/promises');
        const info = await stat(candidate);
        if (info.isFile()) {
          filePath = candidate;
          break;
        }
      } catch {
        /* try the next root */
      }
    }

    if (!filePath || !filePath.startsWith(root)) {
      res.writeHead(404).end('not found');
      return;
    }

    try {
      const body = await readFile(filePath);
      res.writeHead(200, {
        'Content-Type': types[path.extname(filePath)] ?? 'application/octet-stream',
        'Cross-Origin-Opener-Policy': 'same-origin',
        'Cross-Origin-Embedder-Policy': 'require-corp',
        'Cross-Origin-Resource-Policy': 'same-origin',
        'Cache-Control': 'no-store',
      });
      res.end(body);
    } catch {
      res.writeHead(404).end('not found');
    }
  });

  await new Promise((resolve) => server.listen(PORT, '127.0.0.1', resolve));
  return server;
}

async function main() {
  // Chromium by default; set BROWSERGBA_FIREFOX to run the same probe in Gecko.
  const launched = await launchBrowser();
  if (!launched) {
    skipMessage('test:browser');
    return;
  }
  const { browser, engineLabel } = launched;
  console.log(`[test:browser] running in ${engineLabel}`);

  // The fixture ROM is generated, not committed — make sure it exists.
  try {
    await access(path.join(root, 'fixtures', 'test-rom.gba'));
  } catch {
    const { spawnSync } = await import('node:child_process');
    const gen = spawnSync(process.execPath, [path.join(root, 'tools', 'make-test-rom.mjs')], {
      stdio: 'inherit',
    });
    if (gen.status !== 0) throw new Error('failed to generate the fixture ROM');
  }

  await mkdir(path.join(root, 'tests', 'browser', 'artifacts'), { recursive: true });

  const server = await startServer();

  let failure = null;
  try {
    const page = await browser.newPage();
    page.on('pageerror', (error) => console.log('[test:browser] page error:', error.message));
    page.on('console', (message) => {
      const text = message.text();
      if (text.includes('[probe]') || message.type() === 'error') console.log('  ', text);
    });

    await page.goto(`${BASE}/tests/browser/boot.html`, { waitUntil: 'domcontentloaded', timeout: 30000 });
    await page.waitForFunction('window.__probe && window.__probe.ready === true', { timeout: 90000 });

    const results = await page.evaluate(() => window.__probe.results);
    await page.screenshot({ path: path.join(root, 'tests', 'browser', 'artifacts', 'boot.png') });

    console.log('\n[test:browser] probe results:');
    console.log(JSON.stringify(results, null, 2));

    const checks = [
      ['cross-origin isolation granted', results.crossOriginIsolated === true],
      ['core version reported', typeof results.coreVersion === 'string' && results.coreVersion.length > 0],
      ['ROM uploaded to core filesystem', Array.isArray(results.uploaded) && results.uploaded.length > 0],
      ['loadGame returned true', results.loaded === true],
      ['core produced a non-blank frame', results.nonBlank === true],
      ['core reported no fatal error', !results.lastCoreError],
      ['framebuffer is 240x160', results.frameSize?.[0] === 240 && results.frameSize?.[1] === 160],
      ['every pixel matches the deterministic ramp', results.rampOk === true],
      ['ramp still exact while the game runs', results.rampStillOk === true],
      ['animated counter advanced between frames', results.frameAdvanced === true],
      ['A button painted the input marker', results.markerWithA === 0x1f],
      ['releasing A cleared the input marker', results.markerWithoutA === 0],
      ['save state written', Boolean(results.saveState)],
      ['save state loaded', Boolean(results.loadState)],
      ['battery save extracted', typeof results.batterySave === 'number' && results.batterySave > 0],
      ['cartridge save memory holds what the game wrote', results.sramMarker === 0xa5],
      [
        'the exported battery save contains the cartridge data',
        results.saveFileHead?.[0] === 0xa5,
        `head ${JSON.stringify(results.saveFileHead)} (${results.saveFileNonZero} non-zero bytes)`,
      ],
    ];

    // Reported rather than asserted: with this homebrew fixture the core exports a
    // 32 KiB all-zero save file even though the cartridge memory itself answers
    // (see the read-back check). That is mGBA's save-type handling for a cart with
    // no database entry, not app behaviour, and it is recorded as unverified in
    // GAME_PLAN.md instead of being papered over with a passing check.
    console.log(
      `\n[test:browser] note: exported save file has ${results.saveFileNonZero} non-zero bytes ` +
        `(head ${JSON.stringify(results.saveFileHead)}), getSave() reported ${results.batterySave} bytes`,
    );

    console.log('\n[test:browser] checks:');
    for (const [label, pass] of checks) {
      console.log(`  ${pass ? 'PASS' : 'FAIL'}  ${label}`);
      if (!pass && !failure) failure = label;
    }

    if (results.coreError) {
      console.log('\n[test:browser] core error:\n', results.coreError);
    }
  } finally {
    await browser.close();
    server.close();
  }

  if (failure) {
    console.error(`\n[test:browser] FAILED at: ${failure}`);
    process.exitCode = 1;
  } else {
    console.log('\n[test:browser] all checks passed');
  }
}

main().catch((error) => {
  console.error('[test:browser] harness error:', error);
  process.exitCode = 1;
});
